// Parse incoming lead data and extract company size from message
const lead = {
  name: $input.first().json.name,
  email: $input.first().json.email,
  company: $input.first().json.company,
  message: $input.first().json.message,
  budget: $input.first().json.budget || 'unknown',
  submissionDate: new Date().toISOString()
};

// Extract company size from message or estimate from budget
let companySize = 'unknown';
const messageLower = lead.message.toLowerCase();

if (messageLower.includes('1-10') || messageLower.includes('startup') || messageLower.includes('small')) {
  companySize = '1-10';
} else if (messageLower.includes('11-50') || messageLower.includes('growing')) {
  companySize = '11-50';
} else if (messageLower.includes('51-200') || messageLower.includes('mid-size')) {
  companySize = '51-200';
} else if (messageLower.includes('200+') || messageLower.includes('enterprise')) {
  companySize = '200+';
}

// Extract urgency from message
let urgency = 'exploring';
if (messageLower.includes('asap') || messageLower.includes('urgent') || messageLower.includes('immediately')) {
  urgency = 'asap';
} else if (messageLower.includes('1-3 months') || messageLower.includes('next month')) {
  urgency = '1-3 months';
} else if (messageLower.includes('3-6 months') || messageLower.includes('quarter')) {
  urgency = '3-6 months';
}

// Extract AI maturity level
let aiMaturity = 'none';
if (messageLower.includes('advanced') || messageLower.includes('gpt') || messageLower.includes('machine learning')) {
  aiMaturity = 'advanced';
} else if (messageLower.includes('some') || messageLower.includes('chatbot') || messageLower.includes('automation')) {
  aiMaturity = 'some';
}

return {
  json: {
    ...lead,
    companySize,
    urgency,
    aiMaturity
  }
};

// Lead Scoring Algorithm
const lead = $input.first().json;
let score = 0;
const scoreBreakdown = {};

// 1. Company Size Scoring (0-40 points)
const companySizeScores = {
  '1-10': 10,
  '11-50': 20,
  '51-200': 30,
  '200+': 40,
  'unknown': 15
};
score += companySizeScores[lead.companySize] || 0;
scoreBreakdown.companySize = {
  category: lead.companySize,
  points: companySizeScores[lead.companySize] || 0
};

// 2. Budget Scoring (0-70 points)
const budgetScores = {
  '<50k': 10,
  '50-100k': 30,
  '100-250k': 50,
  '250k+': 70,
  'unknown': 5
};
score += budgetScores[lead.budget] || 0;
scoreBreakdown.budget = {
  category: lead.budget,
  points: budgetScores[lead.budget] || 0
};

// 3. Project Urgency Scoring (0-30 points)
const urgencyScores = {
  'asap': 30,
  '1-3 months': 20,
  '3-6 months': 10,
  'exploring': 5,
  'unknown': 5
};
score += urgencyScores[lead.urgency] || 0;
scoreBreakdown.urgency = {
  category: lead.urgency,
  points: urgencyScores[lead.urgency] || 0
};

// 4. AI Maturity Scoring (0-25 points)
const aiMaturityScores = {
  'none': 5,
  'some': 15,
  'advanced': 25
};
score += aiMaturityScores[lead.aiMaturity] || 0;
scoreBreakdown.aiMaturity = {
  category: lead.aiMaturity,
  points: aiMaturityScores[lead.aiMaturity] || 0
};

// Determine qualification tier
let qualification = 'cold';
let tier = 'Newsletter';
let priority = 'Low';

if (score >= 90) {
  qualification = 'hot';
  tier = 'Hot Lead - Sales Call';
  priority = 'Urgent';
} else if (score >= 60) {
  qualification = 'warm';
  tier = 'Warm Lead - Email Nurture';
  priority = 'Medium';
} else {
  qualification = 'cold';
  tier = 'Cold Lead - Newsletter';
  priority = 'Low';
}

return {
  json: {
    ...lead,
    score,
    scoreBreakdown,
    qualification,
    tier,
    priority,
    qualificationId: `${lead.email}-${Date.now()}`,
    processingTime: new Date().toISOString()
  }
};

